static inline void algorithm_memset_store_f64(double * restrict dst, Index_type n, double val)
{
    Index_type i = 0;
    const size_t vlmax = __riscv_vsetvlmax_e64m8();
    const Index_type ivl = (Index_type)vlmax;
    const vfloat64m8_t vval = __riscv_vfmv_v_f_f64m8(val, vlmax);

    if (ivl > 0) {
        const Index_type step4 = ivl * 4;
        for (; i + step4 <= n; i += step4) {
            __riscv_vse64_v_f64m8(dst + i,              vval, vlmax);
            __riscv_vse64_v_f64m8(dst + i + ivl,        vval, vlmax);
            __riscv_vse64_v_f64m8(dst + i + ivl * 2,    vval, vlmax);
            __riscv_vse64_v_f64m8(dst + i + ivl * 3,    vval, vlmax);
        }

        for (; i + ivl <= n; i += ivl) {
            __riscv_vse64_v_f64m8(dst + i, vval, vlmax);
