static inline real_t algorithm_reduce_sum_scalar_real(const real_t *ptr, Index_type len)
{
    real_t s = 0.0;
    for (Index_type i = 0; i < len; ++i) {
        s += ptr[i];
    }
    return s;
}

static inline float algorithm_reduce_sum_rvv_f32(const float *ptr, Index_type len)
{
    float s = 0.0f;
    Index_type i = 0;

    while (i < len) {
        size_t vl = __riscv_vsetvl_e32m8((size_t)(len - i));
        vfloat32m8_t v = __riscv_vle32_v_f32m8(ptr + i, vl);
        vfloat32m1_t init = __riscv_vfmv_s_f_f32m1(s, vl);
        vfloat32m1_t red = __riscv_vfredosum_vs_f32m8_f32m1(v, init, vl);
        s = __riscv_vfmv_f_s_f32m1_f32(red);
        i += (Index_type)vl;
    }

    return s;
}

static inline double algorithm_reduce_sum_rvv_f64(const double *ptr, Index_type len)
{
    double s = 0.0;
    Index_type i = 0;

    while (i < len) {
        size_t vl = __riscv_vsetvl_e64m8((size_t)(len - i));
        vfloat64m8_t v = __riscv_vle64_v_f64m8(ptr + i, vl);
        vfloat64m1_t init = __riscv_vfmv_s_f_f64m1(s, vl);
        vfloat64m1_t red = __riscv_vfredosum_vs_f64m8_f64m1(v, init, vl);
        s = __riscv_vfmv_f_s_f64m1_f64(red);
        i += (Index_type)vl;
    }

    return s;
}

#define ALGORITHM_REDUCE_SUM(ptr, len) \
    _Generic((real_t)0, \
        float: algorithm_reduce_sum_rvv_f32, \
        double: algorithm_reduce_sum_rvv_f64, \
        default: algorithm_reduce_sum_scalar_real \
    )((ptr), (len))
#endif

real_t algorithm_reduce_sum(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t acc = 0.0;
    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        real_t s = ALGORITHM_REDUCE_SUM(x, LEN_1D);
#else
        real_t s = 0.0;
        for (Index_type i = 0; i < LEN_1D; ++i) {
            s += x[i];
        }
#endif
        acc += s;
        dummy(x, NULL, NULL, NULL, NULL, s);
    }
    y[0] = acc / (real_t)(iterations * LEN_1D);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

