real_t apps_del_dot_vec_2d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t half = 0.5f, ptiny = 1.0e-2f;
    const int loop_len = iterations / 4 + 1;

    for (int nl = 0; nl < loop_len; nl++) {
        Index_type i = 0;

        for (; i + 1 < APPS_N1D; i += 2) {
            real_t xi0  = half * ( apps_x1[i]     + apps_x2[i]     - apps_x3[i]     - apps_x4[i]     );
            real_t xj0  = half * ( apps_x2[i]     + apps_x3[i]     - apps_x4[i]     - apps_x1[i]     );
            real_t yi0  = half * ( apps_y1[i]     + apps_y2[i]     - apps_y3[i]     - apps_y4[i]     );
            real_t yj0  = half * ( apps_y2[i]     + apps_y3[i]     - apps_y4[i]     - apps_y1[i]     );
            real_t fxi0 = half * ( apps_fx1[i]    + apps_fx2[i]    - apps_fx3[i]    - apps_fx4[i]    );
            real_t fxj0 = half * ( apps_fx2[i]    + apps_fx3[i]    - apps_fx4[i]    - apps_fx1[i]    );
            real_t fyi0 = half * ( apps_fy1[i]    + apps_fy2[i]    - apps_fy3[i]    - apps_fy4[i]    );
            real_t fyj0 = half * ( apps_fy2[i]    + apps_fy3[i]    - apps_fy4[i]    - apps_fy1[i]    );

            real_t xi1  = half * ( apps_x1[i + 1]  + apps_x2[i + 1]  - apps_x3[i + 1]  - apps_x4[i + 1]  );
            real_t xj1  = half * ( apps_x2[i + 1]  + apps_x3[i + 1]  - apps_x4[i + 1]  - apps_x1[i + 1]  );
            real_t yi1  = half * ( apps_y1[i + 1]  + apps_y2[i + 1]  - apps_y3[i + 1]  - apps_y4[i + 1]  );
            real_t yj1  = half * ( apps_y2[i + 1]  + apps_y3[i + 1]  - apps_y4[i + 1]  - apps_y1[i + 1]  );
            real_t fxi1 = half * ( apps_fx1[i + 1] + apps_fx2[i + 1] - apps_fx3[i + 1] - apps_fx4[i + 1] );
            real_t fxj1 = half * ( apps_fx2[i + 1] + apps_fx3[i + 1] - apps_fx4[i + 1] - apps_fx1[i + 1] );
            real_t fyi1 = half * ( apps_fy1[i + 1] + apps_fy2[i + 1] - apps_fy3[i + 1] - apps_fy4[i + 1] );
            real_t fyj1 = half * ( apps_fy2[i + 1] + apps_fy3[i + 1] - apps_fy4[i + 1] - apps_fy1[i + 1] );

            real_t rarea0 = 1.0f / ( xi0 * yj0 - xj0 * yi0 + ptiny );
            real_t dfxdx0 = rarea0 * ( fxi0 * yj0 - fxj0 * yi0 );
            real_t dfydy0 = rarea0 * ( fyj0 * xi0 - fyi0 * xj0 );
            real_t affine0 = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                             ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );

            real_t rarea1 = 1.0f / ( xi1 * yj1 - xj1 * yi1 + ptiny );
            real_t dfxdx1 = rarea1 * ( fxi1 * yj1 - fxj1 * yi1 );
            real_t dfydy1 = rarea1 * ( fyj1 * xi1 - fyi1 * xj1 );
            real_t affine1 = ( apps_fy1[i + 1] + apps_fy2[i + 1] + apps_fy3[i + 1] + apps_fy4[i + 1] ) /
                             ( apps_y1[i + 1]  + apps_y2[i + 1]  + apps_y3[i + 1]  + apps_y4[i + 1]  );

            apps_div[i]     = dfxdx0 + dfydy0 + affine0;
            apps_div[i + 1] = dfxdx1 + dfydy1 + affine1;
        }

        for (; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
