real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;

    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
#if defined(__riscv_vector)
        Index_type i = 0;

        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(APPS_N1D - i));

            vfloat32m1_t eold  = __riscv_vle32_v_f32m1(&apps_e_old[i], vl);
            vfloat32m1_t delvc = __riscv_vle32_v_f32m1(&apps_delvc[i], vl);
            vfloat32m1_t pold  = __riscv_vle32_v_f32m1(&apps_p_old[i], vl);
            vfloat32m1_t qold  = __riscv_vle32_v_f32m1(&apps_q_old[i], vl);
            vfloat32m1_t work  = __riscv_vle32_v_f32m1(&apps_work[i], vl);

            vfloat32m1_t pq = __riscv_vfadd_vv_f32m1(pold, qold, vl);
            vfloat32m1_t t  = __riscv_vfmul_vv_f32m1(delvc, pq, vl);
            t = __riscv_vfmul_vf_f32m1(t, 0.5f, vl);
            vfloat32m1_t enew = __riscv_vfsub_vv_f32m1(eold, t, vl);
            work = __riscv_vfmul_vf_f32m1(work, 0.5f, vl);
            enew = __riscv_vfadd_vv_f32m1(enew, work, vl);

            __riscv_vse32_v_f32m1(&apps_e_new[i], enew, vl);
            i += (Index_type)vl;
        }

        for (Index_type j = 0; j < APPS_N1D; ++j) {
            if (apps_delvc[j] > 0.0f) {
                apps_q_new[j] = 0.0f;
            } else {
                real_t vhalf = 1.0f / (1.0f + apps_compHalfStep[j]);
                real_t ssc = ( apps_pbvc[j] * apps_e_new[j] +
                               vhalf * vhalf * apps_bvc[j] * apps_pHalfStep[j] ) / rho0;
                if (ssc <= 1.111111e-36f) ssc = 3.333333e-18f;
                else                      ssc = sqrtf(ssc);
                apps_q_new[j] = ssc * apps_ql_old[j] + apps_qq_old[j];
            }
        }

        i = 0;
        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(APPS_N1D - i));

            vfloat32m1_t enew  = __riscv_vle32_v_f32m1(&apps_e_new[i], vl);
            vfloat32m1_t delvc = __riscv_vle32_v_f32m1(&apps_delvc[i], vl);
            vfloat32m1_t pold  = __riscv_vle32_v_f32m1(&apps_p_old[i], vl);
            vfloat32m1_t qold  = __riscv_vle32_v_f32m1(&apps_q_old[i], vl);
            vfloat32m1_t ph    = __riscv_vle32_v_f32m1(&apps_pHalfStep[i], vl);
            vfloat32m1_t qn    = __riscv_vle32_v_f32m1(&apps_q_new[i], vl);

            vfloat32m1_t t1 = __riscv_vfadd_vv_f32m1(pold, qold, vl);
            t1 = __riscv_vfmul_vf_f32m1(t1, 3.0f, vl);
            vfloat32m1_t t2 = __riscv_vfadd_vv_f32m1(ph, qn, vl);
            t2 = __riscv_vfmul_vf_f32m1(t2, 4.0f, vl);
            vfloat32m1_t t = __riscv_vfsub_vv_f32m1(t1, t2, vl);
            t = __riscv_vfmul_vv_f32m1(delvc, t, vl);
            t = __riscv_vfmul_vf_f32m1(t, 0.5f, vl);
            enew = __riscv_vfadd_vv_f32m1(enew, t, vl);

            __riscv_vse32_v_f32m1(&apps_e_new[i], enew, vl);
            i += (Index_type)vl;
        }

        i = 0;
        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(APPS_N1D - i));

            vfloat32m1_t enew = __riscv_vle32_v_f32m1(&apps_e_new[i], vl);
            vfloat32m1_t work = __riscv_vle32_v_f32m1(&apps_work[i], vl);

            work = __riscv_vfmul_vf_f32m1(work, 0.5f, vl);
            enew = __riscv_vfadd_vv_f32m1(enew, work, vl);

            vfloat32m1_t abse = __riscv_vfabs_v_f32m1(enew, vl);
            vbool32_t cutmask = __riscv_vmflt_vf_f32m1_b32(abse, e_cut, vl);
            enew = __riscv_vfmerge_vfm_f32m1(cutmask, enew, 0.0f, vl);

            vbool32_t eminmask = __riscv_vmflt_vf_f32m1_b32(enew, emin, vl);
            enew = __riscv_vfmerge_vfm_f32m1(eminmask, enew, emin, vl);

            __riscv_vse32_v_f32m1(&apps_e_new[i], enew, vl);
            i += (Index_type)vl;
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] = apps_e_old[i] - 0.5f * apps_delvc[i] *
                            (apps_p_old[i] + apps_q_old[i]) + 0.5f * apps_work[i];
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            if (apps_delvc[i] > 0.0f) {
                apps_q_new[i] = 0.0f;
            } else {
                real_t vhalf = 1.0f / (1.0f + apps_compHalfStep[i]);
                real_t ssc = ( apps_pbvc[i] * apps_e_new[i] +
                               vhalf * vhalf * apps_bvc[i] * apps_pHalfStep[i] ) / rho0;
                if (ssc <= 1.111111e-36f) ssc = 3.333333e-18f;
                else                      ssc = sqrtf(ssc);
                apps_q_new[i] = ssc * apps_ql_old[i] + apps_qq_old[i];
            }
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_delvc[i] *
                             ( 3.0f*(apps_p_old[i] + apps_q_old[i]) -
                               4.0f*(apps_pHalfStep[i] + apps_q_new[i]) );
        }
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_e_new[i] += 0.5f * apps_work[i];
            if (ABS(apps_e_new[i]) < e_cut) apps_e_new[i] = 0.0f;
            if (apps_e_new[i] < emin)        apps_e_new[i] = emin;
        }
#endif
        dummy(apps_e_new, apps_q_new, NULL, NULL, NULL, e_cut);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

