real_t lcals_planckian(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
#if defined(__riscv_vector)
        if (sizeof(real_t) == sizeof(float)) {
            float *yf = (float *)y;
            float *wf = (float *)w;
            const float *uf = (const float *)u;
            const float *vf = (const float *)v;
            const float *xf = (const float *)x;

            Index_type i = 0;
            while (i < LEN_1D) {
                const size_t vl = __riscv_vsetvl_e32m8((size_t)(LEN_1D - i));
                const size_t base = (size_t)i;

                vfloat32m8_t vu = __riscv_vle32_v_f32m8(uf + base, vl);
                vfloat32m8_t vv = __riscv_vle32_v_f32m8(vf + base, vl);
                vfloat32m8_t vy = __riscv_vfdiv_vv_f32m8(vu, vv, vl);
                __riscv_vse32_v_f32m8(yf + base, vy, vl);

                float denom[vl];
                for (size_t j = 0; j < vl; ++j) {
                    denom[j] = expf(yf[base + j]) - 1.0f;
                }

                vfloat32m8_t vx = __riscv_vle32_v_f32m8(xf + base, vl);
                vfloat32m8_t vd = __riscv_vle32_v_f32m8(denom, vl);
                vfloat32m8_t vw = __riscv_vfdiv_vv_f32m8(vx, vd, vl);
                __riscv_vse32_v_f32m8(wf + base, vw, vl);

                i += (Index_type)vl;
            }
        } else
#endif
        {
            for (Index_type i = 0; i < LEN_1D; ++i) {
                y[i] = u[i] / v[i];
                w[i] = x[i] / ( expf(y[i]) - 1.0f );
            }
        }

        dummy(y, w, u, v, x, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

