            vfloat64m4_t vacc0 = __riscv_vfmv_v_f_f64m4(0.0, vlmax);
            vfloat64m4_t vacc1 = __riscv_vfmv_v_f_f64m4(0.0, vlmax);

            for (; i + 2 * vlmax <= len; i += 2 * vlmax) {
                vfloat64m4_t va0 = __riscv_vle64_v_f64m4(pa + i, vlmax);
                vfloat64m4_t vb0 = __riscv_vle64_v_f64m4(pb + i, vlmax);
                vfloat64m4_t va1 = __riscv_vle64_v_f64m4(pa + i + vlmax, vlmax);
                vfloat64m4_t vb1 = __riscv_vle64_v_f64m4(pb + i + vlmax, vlmax);
                vacc0 = __riscv_vfmacc_vv_f64m4(vacc0, va0, vb0, vlmax);
                vacc1 = __riscv_vfmacc_vv_f64m4(vacc1, va1, vb1, vlmax);
