                size_t vl = __riscv_vsetvl_e64m4(len - i);
                vfloat64m4_t va = __riscv_vle64_v_f64m4(pa + i, vl);
                vfloat64m4_t vb = __riscv_vle64_v_f64m4(pb + i, vl);
                vacc0 = __riscv_vfmacc_vv_f64m4(vacc0, va, vb, vl);
                i += vl;
