            vacc0 = __riscv_vfadd_vv_f64m4(vacc0, vacc1, vlmax);
            vfloat64m1_t vzero = __riscv_vfmv_v_f_f64m1(0.0, 1);
            vfloat64m1_t vred = __riscv_vfredusum_vs_f64m4_f64m1(vacc0, vzero, vlmax);
            real_t local = (real_t)__riscv_vfmv_f_s_f64m1_f64(vred);

