        const float *pa = (const float *)a;
        const float *pb = (const float *)b;
        const size_t len = (size_t)LEN_1D;
        const size_t vlmax = __riscv_vsetvlmax_e32m4();

        for (int nl = 0; nl < iterations; nl++) {
            size_t i = 0;
            vfloat32m4_t vacc0 = __riscv_vfmv_v_f_f32m4(0.0f, vlmax);
            vfloat32m4_t vacc1 = __riscv_vfmv_v_f_f32m4(0.0f, vlmax);

            for (; i + 2 * vlmax <= len; i += 2 * vlmax) {
                vfloat32m4_t va0 = __riscv_vle32_v_f32m4(pa + i, vlmax);
                vfloat32m4_t vb0 = __riscv_vle32_v_f32m4(pb + i, vlmax);
                vfloat32m4_t va1 = __riscv_vle32_v_f32m4(pa + i + vlmax, vlmax);
                vfloat32m4_t vb1 = __riscv_vle32_v_f32m4(pb + i + vlmax, vlmax);
                vacc0 = __riscv_vfmacc_vv_f32m4(vacc0, va0, vb0, vlmax);
                vacc1 = __riscv_vfmacc_vv_f32m4(vacc1, va1, vb1, vlmax);
