            while (i < len) {
                size_t vl = __riscv_vsetvl_e32m4(len - i);
                vfloat32m4_t va = __riscv_vle32_v_f32m4(pa + i, vl);
                vfloat32m4_t vb = __riscv_vle32_v_f32m4(pb + i, vl);
                vacc0 = __riscv_vfmacc_vv_f32m4(vacc0, va, vb, vl);
                i += vl;
