            vacc0 = __riscv_vfadd_vv_f32m4(vacc0, vacc1, vlmax);
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.0f, 1);
            vfloat32m1_t vred = __riscv_vfredusum_vs_f32m4_f32m1(vacc0, vzero, vlmax);
            real_t local = (real_t)__riscv_vfmv_f_s_f32m1_f32(vred);

